    #Node Switch
    def switch_false( self, switch: Boolean = None, false: Integer = None):
        """Node Switch.
        
        Jump: True
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'INT'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Integer, optional
            Socket 'False' (default: None)
        

        Returns
        -------
        Self
            The updated receiver, or its owning geometry for a domain.
            Updates self from the default output socket.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': false, 'ID_True': self},
            input_type='INT')
        
        self._jump(node._out)
        return self.self_return

    #Node Switch
    @classmethod
    def Switch( cls, switch: Boolean = None, false: Integer = None, true: Integer = None):
        """Node Switch.
        
        Jump: False
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'INT'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Integer, optional
            Socket 'False' (default: None)
        true : Integer, optional
            Socket 'True' (default: None)
        

        Returns
        -------
        Self
            Default output socket wrapped in the calling class.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': false, 'ID_True': true},
            input_type='INT')
        
        return cls(node._out)
